const VALID_TYPES = new Set([
  "charge.success",
  "charge.failed",
  "charge.abandoned",
  "refund.processed",
]);

const TERMINAL_CHARGE_STATUSES = new Set([
  "success",
  "partially_refunded",
  "refunded",
  "amount_mismatch",
]);

const hasOwn = (object, key) =>
  Object.prototype.hasOwnProperty.call(object, key);

export function createLedger({ expectedAmounts = {} } = {}) {
  const amounts = expectedAmounts ?? {};
  const records = new Map();
  const handledIds = new Set();

  function createRecord(reference) {
    const hasExpectedAmount = hasOwn(amounts, reference);
    const expectedAmount = hasExpectedAmount
      ? amounts[reference]
      : null;

    const record = {
      reference,
      status: "pending",
      amountKobo: expectedAmount,
      refundedKobo: 0,
      deferredRefunds: [],
      hasExpectedAmount,
      expectedAmount,
    };

    records.set(reference, record);
    return record;
  }

  function applyRefund(record, amountKobo) {
    const newTotal = record.refundedKobo + amountKobo;

    if (newTotal > record.amountKobo) {
      return false;
    }

    record.refundedKobo = newTotal;
    record.status =
      newTotal === record.amountKobo
        ? "refunded"
        : "partially_refunded";

    return true;
  }

  function handle(event) {
    const type = event == null ? undefined : event.type;

    if (!VALID_TYPES.has(type)) {
      return {
        applied: false,
        reason: "unknown-type",
        status: null,
      };
    }

    const reference = event.reference;
    const id = event.id;
    const currentRecord = records.get(reference);

    if (handledIds.has(id)) {
      return {
        applied: false,
        reason: "duplicate",
        status: currentRecord ? currentRecord.status : null,
      };
    }

    const amountKobo = event.amountKobo;
    const requiresValidAmount =
      type === "charge.success" || type === "refund.processed";

    if (
      requiresValidAmount &&
      (!Number.isInteger(amountKobo) || amountKobo <= 0)
    ) {
      return {
        applied: false,
        reason: "invalid-amount",
        status: currentRecord ? currentRecord.status : null,
      };
    }

    handledIds.add(id);

    const record = currentRecord ?? createRecord(reference);

    if (type !== "refund.processed") {
      if (TERMINAL_CHARGE_STATUSES.has(record.status)) {
        return {
          applied: false,
          reason: "terminal",
          status: record.status,
        };
      }

      if (type === "charge.failed") {
        if (
          record.status === "pending" ||
          record.status === "abandoned"
        ) {
          record.status = "failed";
          return {
            applied: true,
            reason: null,
            status: record.status,
          };
        }

        return {
          applied: false,
          reason: "stale",
          status: record.status,
        };
      }

      if (type === "charge.abandoned") {
        if (record.status === "pending") {
          record.status = "abandoned";
          return {
            applied: true,
            reason: null,
            status: record.status,
          };
        }

        return {
          applied: false,
          reason: "stale",
          status: record.status,
        };
      }

      if (
        record.hasExpectedAmount &&
        amountKobo !== record.expectedAmount
      ) {
        record.status = "amount_mismatch";
        record.deferredRefunds = [];

        return {
          applied: true,
          reason: "amount-mismatch",
          status: record.status,
        };
      }

      record.status = "success";
      record.amountKobo = record.hasExpectedAmount
        ? record.expectedAmount
        : amountKobo;

      const deferredRefunds = record.deferredRefunds;
      record.deferredRefunds = [];

      for (const deferredAmount of deferredRefunds) {
        applyRefund(record, deferredAmount);
      }

      return {
        applied: true,
        reason: null,
        status: record.status,
      };
    }

    if (
      record.status === "success" ||
      record.status === "partially_refunded"
    ) {
      if (!applyRefund(record, amountKobo)) {
        return {
          applied: false,
          reason: "over-refund",
          status: record.status,
        };
      }

      return {
        applied: true,
        reason: null,
        status: record.status,
      };
    }

    if (record.status === "refunded") {
      return {
        applied: false,
        reason: "over-refund",
        status: record.status,
      };
    }

    if (record.status === "amount_mismatch") {
      return {
        applied: false,
        reason: "terminal",
        status: record.status,
      };
    }

    record.deferredRefunds.push(amountKobo);

    return {
      applied: false,
      reason: "deferred",
      status: record.status,
    };
  }

  function get(reference) {
    const record = records.get(reference);

    if (!record) {
      return undefined;
    }

    return {
      reference: record.reference,
      status: record.status,
      amountKobo: record.amountKobo,
      refundedKobo: record.refundedKobo,
    };
  }

  return { handle, get };
}
